import { describe, expect, it } from 'vitest';

import { normalizeGraphvizSvg } from '../src/renderers/graphviz-svg.js';
import { MAX_GRAPHVIZ_SVG_BYTES } from '../src/renderers/graphviz-limits.js';

const VALID_SVG = '<svg width="72pt" height="40px" viewBox="0 0 72 40"><text>ok</text></svg>';

describe('Graphviz SVG normalization', () => {
  it('removes only the known leading Graphviz comments', () => {
    const svg = [
      '<!-- Generated by graphviz version 16.1.0 (20260904.0139',
      ' -->',
      '<!-- Pages: 1 -->',
      VALID_SVG,
    ].join('\n');

    expect(normalizeGraphvizSvg(svg)).toBe(VALID_SVG);
  });

  it('accepts finite positive point and pixel dimensions', () => {
    expect(normalizeGraphvizSvg(VALID_SVG)).toBe(VALID_SVG);
    expect(
      normalizeGraphvizSvg('<svg width="6144pt" height="8192px" viewBox="-2 -3 100 40"/>'),
    ).toContain('<svg');
  });

  it('rejects output larger than four MiB', () => {
    const svg = `<svg width="1px" height="1px" viewBox="0 0 1 1"><text>${'x'.repeat(MAX_GRAPHVIZ_SVG_BYTES)}</text></svg>`;
    expect(() => normalizeGraphvizSvg(svg)).toThrow('SVG is too large');
  });

  it.each([
    ['oversized width', '<svg width="8193px" height="1px" viewBox="0 0 1 1"/>'],
    ['oversized point width', '<svg width="6145pt" height="1px" viewBox="0 0 1 1"/>'],
    ['zero height', '<svg width="1px" height="0px" viewBox="0 0 1 1"/>'],
    ['missing dimensions', '<svg viewBox="0 0 1 1"/>'],
    ['invalid viewBox', '<svg width="1px" height="1px" viewBox="0 0 Infinity 1"/>'],
    ['missing viewBox', '<svg width="1px" height="1px"/>'],
  ])('rejects %s', (_name, svg) => {
    expect(() => normalizeGraphvizSvg(svg)).toThrow();
  });

  it('rejects external SVG links, CSS references, and XML stylesheets', () => {
    for (const href of [
      'https://example.com',
      'file:///etc/passwd',
      'data:image/svg+xml;base64,PHN2Zy8+',
      'javascript:alert(1)',
    ]) {
      expect(() =>
        normalizeGraphvizSvg(
          `<svg width="1px" height="1px" viewBox="0 0 1 1"><a href="${href}"/></svg>`,
        ),
      ).toThrow('non-fragment href');
    }
    expect(() =>
      normalizeGraphvizSvg(
        '<svg width="1px" height="1px" viewBox="0 0 1 1"><style>g{fill:url(https://example.com/a)}</style></svg>',
      ),
    ).toThrow('non-fragment CSS url');
    expect(() =>
      normalizeGraphvizSvg(
        '<?xml-stylesheet href="https://example.com/theme.css"?><svg width="1px" height="1px" viewBox="0 0 1 1"/>',
      ),
    ).toThrow('external stylesheet');
  });

  it('rejects active SVG event attributes and unexpected XML wrappers', () => {
    expect(() =>
      normalizeGraphvizSvg('<svg onload="alert(1)" width="1px" height="1px" viewBox="0 0 1 1"/>'),
    ).toThrow('event attribute');
    expect(() =>
      normalizeGraphvizSvg(
        '<?xml version="1.0"?><svg width="1px" height="1px" viewBox="0 0 1 1"/>',
      ),
    ).toThrow('unexpected XML wrapper');
  });
});
